-- Declarative render-markdown settings are generated by default.nix.
require("render-markdown").setup(require("dotfiles.settings").renderMarkdown)

-- Agentic streams replies into the AgenticChat buffer while the prompt buffer holds
-- focus. render-markdown only refreshes on buffer-local events (TextChanged,
-- CursorMoved, ...) that never fire for a buffer that is not current, so streamed
-- messages stayed raw Markdown until the chat window was entered manually.
-- Redraw the chat buffer whenever its text changes, debounced.
local group = vim.api.nvim_create_augroup("DotfilesAgenticChatRender", { clear = true })
local timers = {}

vim.api.nvim_create_autocmd("FileType", {
  group = group,
  pattern = "AgenticChat",
  callback = function(event)
    local buf = event.buf
    if timers[buf] then
      return
    end
    local timer = assert(vim.uv.new_timer())
    timers[buf] = timer
    vim.api.nvim_buf_attach(buf, false, {
      on_lines = function()
        timer:stop()
        timer:start(
          80,
          0,
          vim.schedule_wrap(function()
            if vim.api.nvim_buf_is_valid(buf) then
              pcall(require("render-markdown").render, { buf = buf })
            end
          end)
        )
      end,
      on_detach = function()
        timer:stop()
        if not timer:is_closing() then
          timer:close()
        end
        timers[buf] = nil
      end,
      on_reload = function() end,
    })
  end,
})
